  "mnemonics": [
    {
      "id": "mn-stable",
      "label": "STABLE",
      "intro": "La décision devant un abdomen traumatisé",
      "entries": [
        {
          "key": "S",
          "term": "Stable ? Si oui : imagerie et surveillance ; si non : bloc d'emblée."
        },
        {
          "key": "T",
          "term": "Tension : hypotension persistante = chirurgie."
        },
        {
          "key": "A",
          "term": "Abdomen répété : la défense peut apparaître en quelques heures."
        },
        {
          "key": "B",
          "term": "Blood : groupe, transfusion, correction de la coagulopathie."
        },
        {
          "key": "L",
          "term": "Lésions associées : thorax, bassin, tête, membres."
        },
        {
          "key": "E",
          "term": "Examen clinique répété et FAST répétable."
        }
      ],
      "note": "La stabilité hémodynamique est la variable qui commande tout le reste."
    }
  ],
  "flashcards": [
    {
      "id": "fc-01",
      "front": "Quelle est la question centrale devant un traumatisé abdominal fermé ?",
      "back": "Le patient est-il hémodynamiquement stable ? Instable = bloc d'emblée, stable = imagerie et surveillance.",
      "tags": [
        "stratégie"
      ]
    },
    {
      "id": "fc-02",
      "front": "Quel examen rapide détecte un hémopéritoine au lit du patient ?",
      "back": "L'échographie FAST.",
      "tags": [
        "diagnostic"
      ]
    },
    {
      "id": "fc-03",
      "front": "Quel est l'examen de référence chez le patient stable ?",
      "back": "La tomodensitométrie abdomino-pelvienne avec injection de produit de contraste.",
      "tags": [
        "diagnostic"
      ]
    },
    {
      "id": "fc-04",
      "front": "Quelles lésions associe-t-on au port de la ceinture de sécurité ?",
      "back": "Des lésions du grêle et du mésentère, une ecchymose abdominale transversale et des fractures lombaires.",
      "tags": [
        "mécanismes"
      ]
    },
    {
      "id": "fc-05",
      "front": "Quels organes saignent le plus dans les traumatismes fermés ?",
      "back": "La rate et le foie.",
      "tags": [
        "lésions"
      ]
    },
    {
      "id": "fc-06",
      "front": "Pourquoi une péritonite peut-elle apparaître tardivement ?",
      "back": "Parce qu'une perforation d'organe creux peut se contenenir quelques heures avant de diffuser : d'où l'examen répété.",
      "tags": [
        "surveillance"
      ]
    },
    {
      "id": "fc-07",
      "front": "Qu'est-ce que le damage control ?",
      "back": "Une laparotomie écourtée : contrôle de l'hémorragie et de la contamination, packing, fermeture provisoire, réanimation, puis réintervention programmée.",
      "tags": [
        "traitement"
      ]
    },
    {
      "id": "fc-08",
